let windowSize = 3h;

// S58: Archive Supply-Chain (Zip Slip) — UAVArchiveAudit_CL엔 UAVId 없음, 전역 게이트로 사용
let S58Time = toscalar(
    UAVArchiveAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where PathTraversalDetected == true
    | summarize min(TimeGenerated));

// S33: Firmware Tamper — UAVPgse_CL, UAVId 보유
let S33 =
    UAVPgse_CL
    | where TimeGenerated > ago(windowSize)
    | where HashMatch == false or Passed == false
    | extend Stage = 'S33', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

// S1: GNSS Spoofing
let S1 =
    UAVTelemetry_CL
    | where TimeGenerated > ago(windowSize)
    | where MsgType == 'EKF_STATUS_REPORT' and PosHorizVariance > 5.0
    | extend Stage = 'S1', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

union S33, S1
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by UAVId
| extend HasS58 = isnotnull(S58Time)
| extend EffectiveStageCount = StageCount + toint(HasS58)
| where EffectiveStageCount >= 2
| extend CampaignType = "C14_아카이브공급망_펌웨어변조_항법거부"
| extend StepSummary = strcat("S58(전역)@", tostring(S58Time), " | Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, UAVId, StagesSeen, EffectiveStageCount, CampaignType, StepSummary, Severity
